                    if v and v.strip():
                        status=v; break
                for c in bd_cols:
                    v=row.get(c)
                    if v and v.strip():
                        bd=v; break
                for c in id_cols:
                    v=row.get(c)
                    if v and v.strip():
                        key=v; break
